// Command gentables regenerates hpack/tables_data.go from the HPACK
// reference implementation vendored into the local Go toolchain.
//
// The generated file only contains constant table data (the static table
// from RFC 7541 section 2.3.1 and the Huffman code table from appendix B),
// so the runtime package has no dependency on the vendored sources.
package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strconv"
)

func main() {
	root := os.Getenv("GOROOT")
	if root == "" {
		fatal("GOROOT is not set")
	}
	dir := filepath.Join(root, "src", "vendor", "golang.org", "x", "net", "http2", "hpack")

	codes, codeLens := parseHuffman(filepath.Join(dir, "tables.go"))
	staticEntries := parseStaticTable(filepath.Join(dir, "static_table.go"))

	var out bytes.Buffer
	fmt.Fprintln(&out, "// Code generated by internal/gentables; DO NOT EDIT.")
	fmt.Fprintln(&out, "// Source: golang.org/x/net/http2/hpack tables (RFC 7541 appendix B / section 2.3.1).")
	fmt.Fprintln(&out)
	fmt.Fprintln(&out, "package hpack")
	fmt.Fprintln(&out)
	fmt.Fprintln(&out, "var huffmanCodes = [256]uint32{")
	for i, c := range codes {
		if i%8 == 0 {
			fmt.Fprint(&out, "\t")
		}
		fmt.Fprintf(&out, "0x%x,", c)
		if i%8 == 7 {
			fmt.Fprintln(&out)
		} else {
			fmt.Fprint(&out, " ")
		}
	}
	fmt.Fprintln(&out, "}")
	fmt.Fprintln(&out)
	fmt.Fprintln(&out, "var huffmanCodeLen = [256]uint8{")
	for i, n := range codeLens {
		if i%16 == 0 {
			fmt.Fprint(&out, "\t")
		}
		fmt.Fprintf(&out, "%d,", n)
		if i%16 == 15 {
			fmt.Fprintln(&out)
		} else {
			fmt.Fprint(&out, " ")
		}
	}
	fmt.Fprintln(&out, "}")
	fmt.Fprintln(&out)
	fmt.Fprintln(&out, "// staticTable holds the 61 entries defined by RFC 7541 section 2.3.1,")
	fmt.Fprintln(&out, "// in 1-based order: staticTable[i-1] is HPACK index i.")
	fmt.Fprintln(&out, "var staticTable = []Field{")
	for _, e := range staticEntries {
		fmt.Fprintf(&out, "\t{Name: %q, Value: %q},\n", e.name, e.value)
	}
	fmt.Fprintln(&out, "}")

	dst := filepath.Join("hpack", "tables_data.go")
	if err := os.WriteFile(dst, out.Bytes(), 0o644); err != nil {
		fatal(err.Error())
	}
	fmt.Printf("wrote %s (%d static entries)\n", dst, len(staticEntries))
}

type entry struct{ name, value string }

func parseFile(path string) *ast.File {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, path, nil, 0)
	if err != nil {
		fatal("parse %s: %v", path, err)
	}
	return file
}

func parseHuffman(path string) (codes [256]uint64, lens [256]uint64) {
	file := parseFile(path)
	want := map[string]*[256]uint64{
		"huffmanCodes":   &codes,
		"huffmanCodeLen": &lens,
	}
	ast.Inspect(file, func(n ast.Node) bool {
		spec, ok := n.(*ast.ValueSpec)
		if !ok || len(spec.Names) != 1 || len(spec.Values) != 1 {
			return true
		}
		dst, known := want[spec.Names[0].Name]
		if !known {
			return true
		}
		lit, ok := spec.Values[0].(*ast.CompositeLit)
		if !ok {
			fatal("unexpected literal for %s", spec.Names[0].Name)
		}
		for i, elt := range lit.Elts {
			basic, ok := elt.(*ast.BasicLit)
			if !ok || basic.Kind != token.INT || i >= 256 {
				fatal("unexpected element for %s at %d", spec.Names[0].Name, i)
			}
			v, err := strconv.ParseUint(basic.Value, 0, 64)
			if err != nil {
				fatal("bad int %q: %v", basic.Value, err)
			}
			dst[i] = v
		}
		return true
	})
	return
}

func parseStaticTable(path string) []entry {
	file := parseFile(path)
	var entries []entry
	ast.Inspect(file, func(n ast.Node) bool {
		lit, ok := n.(*ast.CompositeLit)
		if !ok {
			return true
		}
		at, ok := lit.Type.(*ast.ArrayType)
		if !ok {
			return true
		}
		if id, ok := at.Elt.(*ast.Ident); !ok || id.Name != "HeaderField" {
			return true
		}
		for _, elt := range lit.Elts {
			row, ok := elt.(*ast.CompositeLit)
			if !ok {
				fatal("unexpected static table row")
			}
			var e entry
			for _, kv := range row.Elts {
				kvExpr, ok := kv.(*ast.KeyValueExpr)
				if !ok {
					continue
				}
				key, ok := kvExpr.Key.(*ast.Ident)
				if !ok {
					continue
				}
				val, ok := kvExpr.Value.(*ast.BasicLit)
				if !ok || val.Kind != token.STRING {
					continue
				}
				s, err := strconv.Unquote(val.Value)
				if err != nil {
					fatal("bad string %q: %v", val.Value, err)
				}
				switch key.Name {
				case "Name":
					e.name = s
				case "Value":
					e.value = s
				}
			}
			entries = append(entries, e)
		}
		return false
	})
	if len(entries) != 61 {
		fatal("expected 61 static table entries, got %d", len(entries))
	}
	return entries
}

func fatal(format string, args ...any) {
	fmt.Fprintf(os.Stderr, "gentables: "+format+"\n", args...)
	os.Exit(1)
}
